cd /tmp/models && python3 -c "
import pickletools, glob
for f in sorted(glob.glob('model_*.pkl')):
    print('='*20, f, '='*20)
    data = open(f,'rb').read()
    try:
        ops = [(op.name, arg) for op, arg, _ in pickletools.genops(data)]
        for name, arg in ops:
            print(name, repr(arg)[:120])
    except Exception as e:
        print('ERR', e)
" 2>&1 | head -150

